package dev.astralreach.hytale;
import com.hypixel.hytale.component.*;import com.hypixel.hytale.server.core.entity.entities.Player;import com.hypixel.hytale.server.core.entity.entities.player.hud.CustomUIHud;import com.hypixel.hytale.server.core.modules.entity.component.*;import com.hypixel.hytale.server.core.modules.interaction.InteractionModule;import com.hypixel.hytale.server.core.modules.time.WorldTimeResource;import com.hypixel.hytale.server.core.ui.builder.UICommandBuilder;import com.hypixel.hytale.server.core.universe.*;import com.hypixel.hytale.server.core.universe.world.storage.EntityStore;import dev.astralreach.core.StationPass;import java.util.*;import java.util.concurrent.*;
/** Native held spyglass zoom owns the camera. This adds only identity HUD and projection detail. */
final class Observatory{
 private record Scope(Store<EntityStore>store,PlayerRef player,Object connection){}
 private static final Map<UUID,Scope>scopes=new ConcurrentHashMap<>();
 static boolean scoping(UUID id){return scopes.containsKey(id);}
 static void end(Store<EntityStore>s,Ref<EntityStore>r,PlayerRef p){var old=scopes.remove(p.getUuid());if(old==null||old.store()!=s||r==null||!r.isValid()||r.getStore()!=s)return;var player=s.getComponent(r,Player.getComponentType());if(player!=null)player.getHudManager().removeCustomHud(p,Hud.KEY);}
 static void tick(Store<EntityStore>s){var w=s.getExternalData().getWorld();for(var p:w.getPlayerRefs()){var r=p.getReference();if(r==null||!r.isValid()||r.getStore()!=s)continue;var player=s.getComponent(r,Player.getComponentType());if(player==null)continue;if(player.getPageManager().getCustomPage() instanceof StationTrackerPage page)page.refresh(s,r);if(player.getPageManager().getCustomPage() instanceof StationSystemsPage page)page.refresh(s,r);var old=scopes.get(p.getUuid());if(old!=null&&(old.store()!=s||old.player()!=p||old.connection()!=p.getPacketHandler()))scopes.remove(p.getUuid(),old);
  var held=player.getInventory().getItemInHand();var f=s.getComponent(r,AstralReachPlugin.flightType);boolean looking=false;var wield=s.getComponent(r,com.hypixel.hytale.server.core.entity.damage.DamageDataComponent.getComponentType());looking=held!=null&&held.getItemId().equals("AR_Telescope")&&wield!=null&&wield.getCurrentWielding()!=null&&wield.getCurrentWielding().getId().equals("AR_Telescope_Wield")&&StationFlyovers.surface(w)&&(f==null||!f.boarded);
  if(!looking){end(s,r,p);continue;}if(!scopes.containsKey(p.getUuid())){scopes.put(p.getUuid(),new Scope(s,p,p.getPacketHandler()));LunarEnvironment.interior(s,r,p,"AR_observatory_handling");}
  var head=s.getComponent(r,HeadRotation.getComponentType());var position=s.getComponent(r,TransformComponent.getComponentType());String target="Aim at a station light";double best=Math.cos(Math.toRadians(2));if(head!=null&&position!=null){var direction=head.getDirection();double hour=s.getResource(WorldTimeResource.getResourceType()).getDayProgress()*24;var at=position.getPosition();for(var entry:StationSkyCatalog.entries()){var pass=StationPass.sample(entry.owner(),System.currentTimeMillis()/1000d,at.x,at.z,hour);var v=pass.direction();double dot=direction.dot(v.x(),v.y(),v.z());if(pass.brightness()>=.015&&dot>best){best=dot;target=entry.name()+" · "+entry.ownerName()+" · "+Math.round(Math.toDegrees(pass.elevation()))+"°";}}}
  var current=player.getHudManager().getCustomHud(Hud.KEY);Hud hud;if(current instanceof Hud h)hud=h;else{hud=new Hud(p);player.getHudManager().addCustomHud(p,hud);}hud.target(target);
 }
 for(var e:new ArrayList<>(scopes.entrySet()))if(e.getValue().store()==s){var p=e.getValue().player();var r=p.getReference();if(r==null||!r.isValid()||r.getStore()!=s||Universe.get().getPlayer(p.getUuid())!=p)scopes.remove(e.getKey(),e.getValue());}}
 private static final class Hud extends CustomUIHud{static final String KEY="AstralReach.Telescope";private String last="";Hud(PlayerRef p){super(p,KEY,10);}@Override protected void build(UICommandBuilder c){c.append("Pages/AstralReach/TelescopeHud.ui");}void target(String text){if(text.equals(last))return;last=text;var c=new UICommandBuilder();c.set("#Target.Text",text);c.set("#Hint.Text","Hold secondary to look · release to lower telescope");update(false,c);}}
 private Observatory(){}
}
